#include "CurveEditor.h"
#include <algorithm>
CurveEditor::CurveEditor(ScratchPadAudioProcessor& p):processor(p){setMouseCursor(juce::MouseCursor::PointingHandCursor);startTimerHz(60);}
void CurveEditor::resized(){plot=getLocalBounds().toFloat().reduced(2);plot.removeFromLeft(28);plot.removeFromBottom(17);plot.removeFromTop(4);plot.removeFromRight(4);}
float CurveEditor::visibleX(float x)const{return plot.getX()+(x-viewStart)/viewWidth*plot.getWidth();}
juce::Point<float> CurveEditor::point(const CurveNode& n)const{return {visibleX(n.x),plot.getCentreY()-n.y*plot.getHeight()*.25f};}
CurveNode CurveEditor::fromPoint(juce::Point<float> p,bool snap)const{float x=juce::jlimit(0.f,1.f,viewStart+(p.x-plot.getX())/plot.getWidth()*viewWidth);float y=juce::jlimit(-2.f,2.f,(plot.getCentreY()-p.y)*4.f/plot.getHeight());if(snap){x=std::round(x*64)/64.f;y=std::round(y*8)/8.f;}return {x,y,0};}
void CurveEditor::paint(juce::Graphics& g){g.fillAll(Theme::panel);g.setColour(juce::Colours::grey.withAlpha(.55f));g.drawRect(getLocalBounds(),1);g.setFont(Theme::font(10));for(int k=-2;k<=2;++k){float y=plot.getCentreY()-k*plot.getHeight()/4.f;g.setColour(Theme::light.withAlpha(k==0?.35f:.18f));g.drawHorizontalLine((int)y,plot.getX(),plot.getRight());g.setColour(Theme::light.withAlpha(.8f));g.drawText(juce::String(k>0?"+":"")+juce::String(k)+" x",2,(int)y-6,26,12,juce::Justification::centredRight);}
 int lines=64;for(int i=0;i<=lines;++i){float x=visibleX(i/(float)lines);if(x<plot.getX()||x>plot.getRight())continue;g.setColour(Theme::light.withAlpha(i%4==0?.27f:.10f));g.drawVerticalLine((int)x,plot.getY(),plot.getBottom());}
 auto snapshot=processor.curveSnapshot();auto& n=snapshot->nodes;juce::Graphics::ScopedSaveState clip(g);g.reduceClipRegion(plot.toNearestInt());juce::Path path;bool first=true;for(size_t i=0;i<n.size();++i){auto p=point(n[i]);if(first){path.startNewSubPath(p);first=false;}else{auto a=point(n[i-1]);for(int j=1;j<=24;++j){float t=j/24.f;float y=n[i-1].y+(n[i].y-n[i-1].y)*t+n[i-1].tension*4*t*(1-t);float x=a.x+(p.x-a.x)*t;path.lineTo(x,plot.getCentreY()-y*plot.getHeight()*.25f);}}}g.setColour(Theme::red);g.strokePath(path,juce::PathStrokeType(1.7f));for(const auto& a:n){auto p=point(a);g.setColour(Theme::red);g.fillEllipse(p.x-4.1f,p.y-4.1f,8.2f,8.2f);}
 for(int i=0;i<5;++i){float pos=processor.playhead.load()-i*.007f;if(pos<0)pos+=1;auto it=std::upper_bound(n.begin(),n.end(),pos,[](float x,const CurveNode& q){return x<q.x;});float y=n.front().y;if(it!=n.begin()&&it!=n.end()){auto&a=*(it-1);auto&b=*it;float t=(pos-a.x)/std::max(.0001f,b.x-a.x);y=a.y+(b.y-a.y)*t+a.tension*4*t*(1-t);}auto p=point({pos,y,0});g.setColour(Theme::cyan.withAlpha(1.f-i*.18f));g.fillEllipse(p.x-2.8f,p.y-2.8f,5.6f,5.6f);}g.setColour(Theme::cyan.withAlpha(.42f));g.drawVerticalLine((int)visibleX(processor.playhead.load()),plot.getY(),plot.getBottom());
 g.setColour(Theme::light.withAlpha(.18f));g.fillRoundedRectangle(14,getHeight()-11,getWidth()-18,7,3.5f);g.setColour(Theme::light.withAlpha(.55f));g.fillRoundedRectangle(14+viewStart*(getWidth()-18),getHeight()-11,(getWidth()-18)*viewWidth,7,3.5f);
}
void CurveEditor::timerCallback(){float p=processor.playhead.load();if(p!=lastPosition){lastPosition=p;repaint();}}
void CurveEditor::edit(const std::function<void(std::vector<CurveNode>&)>& f){auto copy=processor.curveSnapshot()->nodes;f(copy);processor.setCurve(std::move(copy));repaint();}
void CurveEditor::mouseDown(const juce::MouseEvent& e){if(e.mods.isPopupMenu()){contextMenu();return;}if(e.position.y>getHeight()-14){draggingScroll=true;return;}if(!plot.contains(e.position))return;auto c=processor.curveSnapshot();float best=11.f;dragged=-1;bend=-1;for(int i=0;i<(int)c->nodes.size();++i){auto p=point(c->nodes[(size_t)i]);float d=p.getDistanceFrom(e.position);if(d<best){best=d;dragged=i;}}if(dragged<0){for(int i=0;i<(int)c->nodes.size()-1;++i){auto a=point(c->nodes[(size_t)i]);auto b=point(c->nodes[(size_t)i+1]);auto mid=(a+b)*.5f;mid.y-=c->nodes[(size_t)i].tension*plot.getHeight()*.25f;if(mid.getDistanceFrom(e.position)<9){bend=i;break;}}}if(dragged<0&&bend<0){auto node=fromPoint(e.position,!e.mods.isAltDown());edit([&](auto& v){v.push_back(node);});auto v=processor.curveSnapshot();for(int i=0;i<(int)v->nodes.size();++i)if(std::abs(v->nodes[(size_t)i].x-node.x)<.0001f){dragged=i;break;}}}
void CurveEditor::mouseDrag(const juce::MouseEvent& e){if(draggingScroll){viewStart=juce::jlimit(0.f,1.f-viewWidth,viewStart+(e.position.x-e.mouseDownPosition.x)*viewWidth/plot.getWidth()*.03f);repaint();return;}if(dragged>=0){auto v=fromPoint(e.position,!e.mods.isAltDown());edit([&](auto& nodes){if(dragged<(int)nodes.size()){v.tension=nodes[(size_t)dragged].tension;float low=dragged>0?nodes[(size_t)dragged-1].x+.0001f:0;float high=dragged+1<(int)nodes.size()?nodes[(size_t)dragged+1].x-.0001f:1;v.x=juce::jlimit(low,high,v.x);nodes[(size_t)dragged]=v;}});}else if(bend>=0){edit([&](auto& v){if(bend+1<(int)v.size()){float ya=(v[(size_t)bend].y+v[(size_t)bend+1].y)*.5f;float target=(plot.getCentreY()-e.position.y)*4.f/plot.getHeight();v[(size_t)bend].tension=juce::jlimit(-2.f,2.f,target-ya);}});}}
void CurveEditor::mouseUp(const juce::MouseEvent&){dragged=bend=-1;draggingScroll=false;}
void CurveEditor::mouseDoubleClick(const juce::MouseEvent& e){auto v=processor.curveSnapshot();for(int i=0;i<(int)v->nodes.size();++i)if(point(v->nodes[(size_t)i]).getDistanceFrom(e.position)<12){edit([i](auto& a){if(a.size()>2)a.erase(a.begin()+i);});break;}}
void CurveEditor::mouseWheelMove(const juce::MouseEvent& e,const juce::MouseWheelDetails& w){if(e.mods.isCtrlDown()){float center=viewStart+viewWidth*.5f;viewWidth=juce::jlimit(.125f,1.f,viewWidth*(w.deltaY>0?.85f:1.15f));viewStart=juce::jlimit(0.f,1.f-viewWidth,center-viewWidth*.5f);}else viewStart=juce::jlimit(0.f,1.f-viewWidth,viewStart-w.deltaY*.1f*viewWidth);repaint();}
void CurveEditor::contextMenu(){juce::PopupMenu m;m.addItem(1,"Clear");m.addItem(2,"Invert");m.addItem(3,"Reverse");m.addItem(4,"Stretch 2x");juce::PopupMenu presets;presets.addItem(10,"Classic Scratch");presets.addItem(11,"Tape Brake");presets.addItem(12,"Reverse Rise");m.addSubMenu("Presets",presets);juce::Component::SafePointer<CurveEditor> safe(this);m.showMenuAsync(juce::PopupMenu::Options().withTargetComponent(this),[safe](int n){if(!safe)return;safe->edit([n](auto& v){if(n==1)v={{0,0,0},{1,0,0}};if(n==2)for(auto& a:v)a.y=-a.y;if(n==3){for(auto& a:v)a.x=1-a.x;std::reverse(v.begin(),v.end());}if(n==4)for(auto& a:v)a.x=juce::jlimit(0.f,1.f,a.x*2);if(n==10)v={{0,1,0},{.07f,-1,0},{.14f,1,0},{.21f,-1,0},{.30f,1,0},{1,0,0}};if(n==11)v={{0,1,0},{.5f,.55f,-.13f},{1,0,0}};if(n==12)v={{0,-1,0},{.5f,-.5f,.1f},{1,1,0}};});});}
